      const text = productDemo.classList.contains('demo-collapsed') ? 'Expand' : 'Collapse';
      demoToggle.innerHTML = `<i data-lucide="chevron-down" style="width: 16px; height: 16px;"></i> ${text}`;
      lucide.createIcons();
